// Per-locale @font-face stylesheets, generated by scripts/locale-fonts/build-locale-fonts.ts. They
// are linked (not bundled) so a visitor only downloads the unicode-range table for their locale.
import ja from "./locale-fonts-ja.css?url";
import ko from "./locale-fonts-ko.css?url";
import ru from "./locale-fonts-ru.css?url";
import zhHans from "./locale-fonts-zh-Hans.css?url";
import zhHant from "./locale-fonts-zh-Hant.css?url";

import type { LocaleCode } from "#lib/types/locale.js";

const LOCALE_FONT_STYLESHEETS: Partial<Record<LocaleCode, string>> = {
  ja,
  ko,
  ru,
  "zh-Hans": zhHans,
  "zh-Hant": zhHant,
};

/** Returns the stylesheet URL for locales whose fonts are not covered by the base Latin faces. */
export function localeFontStylesheet(locale: LocaleCode): string | undefined {
  return LOCALE_FONT_STYLESHEETS[locale];
}
